  const uptime = client.getUptime();
  const resMsg = `🟢 *GURU-MD IS ONLINE* 🟢\n\n⚡ Uptime: ${uptime}\n📱 Platform: Multi-device Node\n🛠️ Latency: ${Date.now() - message.timestamp * 1000}ms`;
