/**
 * GURU-XD Terminal Copilot V2 - Interactive Trivia Quiz Handler
 * Command: .quiz
 * Description: Initiates a trivia game. The first participant to type the correct answer 
 *              wins economy coins. Includes a 30-second timeout.
 * 
 * Note: Adjust the database interaction section to match your actual database scheme
 * (e.g., MongoDB, Quick.db, PostgreSQL, or local JSON).
 */

// Global state to track active games per chat session
if (!global.activeQuizzes) {
  global.activeQuizzes = new Map();
}

// Sample trivia dataset (expand or replace with an external API call like OpenTDB if desired)
const TRIVIA_DATABASE = [
  { question: "What is the capital city of Japan?", answer: "tokyo" },
  { question: "Which planet is known as the Red Planet?", answer: "mars" },
  { question: "What is the square root of 144?", answer: "12" },
  { question: "Who painted the famous 'Mona Lisa'?", answer: "leonardo da vinci" },
  { question: "What is the chemical symbol for Gold?", answer: "au" },
  { question: "Which ocean is the largest on Earth?", answer: "pacific" },
  { question: "How many bones are there in an adult human body?", answer: "206" },
  { question: "What is the fastest land animal?", answer: "cheetah" },
  { question: "In which year did the Titanic sink?", answer: "1912" },
  { question: "Which programming language is known as the backbone of web development?", answer: "javascript" }
];

// Configuration
const REWARD_COINS = 150; // Amount of coins rewarded
const TIMEOUT_DURATION = 30000; // 30 seconds to answer

module.exports = async (client, message, args) => {
  // Extract Chat ID and Sender ID depending on library implementation (Baileys/WA-Web.js)
  const chatId = message.from || message.chat || message.key?.remoteJid;
  const senderId = message.sender || message.author || message.key?.participant || message.participant;

  if (!chatId) {
    console.error("[QUIZ ERROR] Unable to resolve Chat ID.");
    return;
  }

  // Prevent duplicate concurrent games in the same chat
  if (global.activeQuizzes.has(chatId)) {
    const activeMsg = "⚠️ *A quiz is already active in this chat!* Answer that one before starting a new game.";
    return client.sendMessage ? await client.sendMessage(chatId, { text: activeMsg }) : await message.reply(activeMsg);
  }

  // Select a random trivia question
  const randomIndex = Math.floor(Math.random() * TRIVIA_DATABASE.length);
  const quiz = TRIVIA_DATABASE[randomIndex];

  global.activeQuizzes.set(chatId, {
    question: quiz.question,
    answer: quiz.answer.toLowerCase().trim(),
    startTime: Date.now()
  });

  const invitationMessage = `🧠 *GURU-XD TRIVIA MINI-GAME* 🧠\n\n` +
    `*Question:* ${quiz.question}\n\n` +
    `💰 *Reward:* \`${REWARD_COINS} Coins\`\n` +
    `⏱️ *Time Limit:* 30 seconds!\n\n` +
    `_Type your answer directly in the chat!_`;

  if (client.sendMessage) {
    await client.sendMessage(chatId, { text: invitationMessage });
  } else {
    await message.reply(invitationMessage);
  }

  // Define Message Collector Listener
  const messageListener = async (msg) => {
    // Ensure message belongs to the current chat
    const msgChatId = msg.from || msg.chat || msg.key?.remoteJid;
    if (msgChatId !== chatId) return;

    // Extract text body
    const text = (msg.body || msg.text || msg.message?.conversation || msg.message?.extendedTextMessage?.text || "").toLowerCase().trim();
    if (!text) return;

    const activeQuiz = global.activeQuizzes.get(chatId);
    if (!activeQuiz) return;

    // Check if the input matches the correct answer
    if (text === activeQuiz.answer) {
      // Clean up game session and remove listener
      cleanupGame();

      const winnerId = msg.sender || msg.author || msg.key?.participant || msg.participant || senderId;
      const winnerName = msg.pushName || "Player";

      // --- DATABASE INTEGRATION BLOCK ---
      // Replace the block below with your actual database update code.
      // Example for a global JSON/object DB structure:
      try {
        if (!global.db) global.db = {};
        if (!global.db.users) global.db.users = {};
        if (!global.db.users[winnerId]) {
          global.db.users[winnerId] = { coins: 0, xp: 0 };
        }

        // Add coins to ledger
        global.db.users[winnerId].coins += REWARD_COINS;
        const currentBalance = global.db.users[winnerId].coins;

        const winMessage = `🎉 *CONGRATULATIONS!* 🎉\n\n` +
          `👤 *Winner:* @${winnerId.split('@')[0]}\n` +
          `✅ *Correct Answer:* *${quiz.answer.toUpperCase()}*\n` +
          `🪙 *Earned:* +${REWARD_COINS} Coins!\n` +
          `🏦 *New Balance:* ${currentBalance} Coins`;

        if (client.sendMessage) {
          await client.sendMessage(chatId, { 
            text: winMessage, 
            mentions: [winnerId] 
          });
        } else {
          await message.reply(winMessage);
        }
      } catch (dbErr) {
        console.error("[DATABASE ERROR] Failed to update economy ledger:", dbErr);
        const errMessage = `🎉 *Correct!* The answer was *${quiz.answer.toUpperCase()}*.\n⚠️ Economy ledger database update failed.`;
        if (client.sendMessage) {
          await client.sendMessage(chatId, { text: errMessage });
        } else {
          await message.reply(errMessage);
        }
      }
    }
  };

  // Register listener (Adapts dynamically depending on your engine's emitter)
  const emitter = client.ev || client; 
  const eventName = client.ev ? 'messages.upsert' : 'message';

  // Normalize message interceptor helper
  const interceptor = async (m) => {
    // Handle Baileys wrapped structure if applicable
    if (eventName === 'messages.upsert') {
      const msgRaw = m.messages[0];
      if (!msgRaw || msgRaw.key.fromMe) return;
      await messageListener(msgRaw);
    } else {
      if (m.fromMe) return;
      await messageListener(m);
    }
  };

  emitter.on(eventName, interceptor);

  // Set timeout sequence for failure to answer
  const timeoutId = setTimeout(async () => {
    if (global.activeQuizzes.has(chatId)) {
      cleanupGame();
      const timeOutMsg = `⏰ *TIME'S UP!* ⏰\n\nNo one answered correctly in time.\n📝 *Correct Answer:* *${quiz.answer.toUpperCase()}*`;
      if (client.sendMessage) {
        await client.sendMessage(chatId, { text: timeOutMsg });
      } else {
        await message.reply(timeOutMsg);
      }
    }
  }, TIMEOUT_DURATION);

  // Game state cleanup routine
  function cleanupGame() {
    clearTimeout(timeoutId);
    emitter.off(eventName, interceptor);
    global.activeQuizzes.delete(chatId);
  }
};

/**
 * GURU-XD Terminal Command: Menu / Help Command List
 * Description: Dynamically lists and categories all registered system commands.
 */

module.exports = async (client, message, args) => {
  try {
    // 1. Fetch registered commands from core instance (assuming Map/Object collection)
    const commands = client.commands;

    if (!commands || (commands instanceof Map ? commands.size === 0 : Object.keys(commands).length === 0)) {
      const errorMsg = "❌ *System Error:* Command registry is empty or inaccessible.";
      return await sendMessage(client, message, errorMsg);
    }

    // 2. Initialize metadata
    const botName = client.user?.name || "GURU-XD BOT";
    const uptime = process.uptime();
    const formattedUptime = formatUptime(uptime);

    // 3. Group commands by category
    const categories = {};

    // Support both Map collection and Standard Object registry
    const commandList = commands instanceof Map ? Array.from(commands.values()) : Object.values(commands);

    commandList.forEach((cmd) => {
      // Prevent mapping duplicate aliases
      if (cmd.alias && cmd.alias.includes(cmd.name)) return; 

      const category = cmd.category ? cmd.category.toUpperCase() : "GENERAL";
      if (!categories[category]) {
        categories[category] = [];
      }

      if (!categories[category].some(c => c.name === cmd.name)) {
        categories[category].push({
          name: cmd.name,
          description: cmd.description || "No description provided."
        });
      }
    });

    // 4. Construct terminal-styled layout
    let menuHeader = `╭━━━〔 *${botName}* 〕━━━┈\n`;
    menuHeader += `┃ 🖥️ *OS*: Node.js ${process.version}\n`;
    menuHeader += `┃ ⏱️ *Uptime*: ${formattedUptime}\n`;
    menuHeader += `┃ 📊 *Commands Loaded*: ${commandList.length}\n`;
    menuHeader += `╰━━━━━━━━━━━━━━━━━━━━┈\n\n`;

    let menuBody = "";
    for (const [category, list] of Object.entries(categories)) {
      menuBody += `┌───〔 *${category}* 〕\n`;
      list.forEach((cmd) => {
        menuBody += `│  🛠️ *.${cmd.name}* \n`;
      });
      menuBody += `└──────────────┈\n\n`;
    }

    const menuFooter = `_💡 Note: Use command prefix [. / !] followed by command name._`;
    const finalMenu = menuHeader + menuBody + menuFooter;

    // 5. Send message (supports WhatsApp Baileys or Telegram context wrappers)
    await sendMessage(client, message, finalMenu);

  } catch (error) {
    console.error("GURU-XD SYSTEM ERROR (Menu handler):", error);
    await sendMessage(client, message, "⚠️ *Error: Internal Terminal module failed to load Menu.*");
  }
};

/**
 * Universal sender helper adapting to WhatsApp/Telegram abstractions
 */
async function sendMessage(client, msg, text) {
  const target = msg.key?.remoteJid || msg.chat || msg.from;
  if (client.sendMessage) {
    return await client.sendMessage(target, { text: text }, { quoted: msg });
  } else if (msg.reply) {
    return await msg.reply(text);
  }
}

/**
 * System Uptime Formatter
 */
function formatUptime(seconds) {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.floor(seconds % 60);
  return `${h}h ${m}m ${s}s`;
}

